import hashlib

class CacheKeyGenerator:
    def __init__(self, salt="default_salt"):
        self.salt = salt

    def generate_key(self, data):
        """dataを基にキャッシュキーを生成"""
        if not isinstance(data, (str, bytes)):
            data = str(data)

        hashed = hashlib.sha256()
        hashed.update(data.encode())
        hashed.update(self.salt.encode())

        return hashed.hexdigest()

