import time

def fetch_data():
    retries = 3
    delay = 1
    for i in range(retries):
        try:
            # サービス呼び出しの擬似コード
            print(f"Attempt {i+1}")
            return "成功"
        except Exception as e:
            print(f"Error: {e}")
            if i == retries - 1:
                raise
            time.sleep(delay)
            delay *= 2

if __name__ == "__main__":
    try:
        result = fetch_data()
        print(result)
    except Exception:
        print("最終的なリトライ失敗")

