        ('/usr/local/../bin', '/usr/bin'),
        ('home//user/./docs', 'home/user/docs'),
        ('C:\\Users\\user\\Documents', 'C:\Users\user\Documents')
    ]
    for input_path, expected in examples:
        result = normalize_path(input_path)
        print(f"{input_path} => {result} ({'一致' if result == expected else '不一致'} )")

