import re

def parse_url(url):
    try:
        # 業務ロジック: URLからドメインを抽出
        match = re.match(r'https?://([^/]+)', url)
        if not match:
            raise ValueError('無効なURL形式')
        return match.group(1)
    except Exception as e:
        print(f'解析エラー: {str(e)}')
        return None

if __name__ == '__main__':
    test_urls = [
        'https://example.com/path',
        'ftp://invalid.net',
        'http://sub.domain.co.jp'
    ]
    for url in test_urls:
        result = parse_url(url)
        print(f'{url} → {result}')

